function isOwner(user, invoice) {
  return invoice.ownerId === user.id;
}

function canView(user, invoice) {
  return invoice.ownerId === user.id || user.role === "billing-admin";
}

function canViewInvoice(user, invoice) {
  const isOwner = invoice.ownerId === user.id;
  const isAdmin = user.role === "billing-admin";
  return isOwner || isAdmin;
}

function invoiceStatus(user, invoice) {
  if (!user) return 401;
  if (!invoice) return 404;
  const isOwner = invoice.ownerId === user.id;
  const isAdmin = user.role === "billing-admin";
  if (!isOwner && !isAdmin) return 403;
  return 200;
}

function canViewShared(user, invoice) {
  const shared = invoice.sharedWithUserIds || [];
  return (
    invoice.ownerId === user.id ||
    user.role === "billing-admin" ||
    shared.includes(user.id)
  );
}

function canViewTeam(user, invoice) {
  const teams = user.teamIds || [];
  return user.role === "billing-admin" || teams.includes(invoice.teamId);
}
